/**
 * Defines a collision group for coarse filtering. When a collision 
 * occurs between two objects that have a PhysicsCollisionGroup assigned,
 * they will collide with each other unless this PhysicsCollisionGroup pair 
 * is filtered. See filteredGroups attribute.
 *
 * A CollectionAPI:colliders maintains a list of PhysicsCollisionAPI rel-s that 
 * defines the members of this Collisiongroup.
 */
export class CollisionGroup extends Typed {
  static readonly typeName: string = "PhysicsCollisionGroup"

  static get(stage: Stage, path: string): CollisionGroup {
    return new CollisionGroup(stage.getPrim(path), stage)
  }
  static define(stage: Stage, path: string): CollisionGroup {
    return new CollisionGroup(stage.definePrim(path, "PhysicsCollisionGroup"), stage)
  }

  isValid(): boolean {
    return super.isValid() && this.prim.isA(CollisionGroup.typeName)
  }

  static getSchemaAttributeNames(includeInherited = true): string[] {
    const names = includeInherited
      ? ["physics:mergeGroup","physics:invertFilteredGroups"]
      : ["physics:mergeGroup","physics:invertFilteredGroups"]
    return names
  }

  /**
   * If non-empty, any collision groups in a stage with a matching
   * mergeGroup should be considered to refer to the same collection. Matching
   * collision groups should behave as if there were a single group containing
   * referenced colliders and filter groups from both collections.
   */
  getMergeGroupNameAttr(): Attribute {
    return this.prim.getAttr(UsdPhysicsTokens.physicsMergeGroup)!
  }
  createMergeGroupNameAttr(defaultValue?: unknown, writeSparsely = false): Attribute {
    return this._createAttr(UsdPhysicsTokens.physicsMergeGroup, "string", false, "varying", defaultValue, writeSparsely)
  }

  /**
   * Normally, the filter will disable collisions against the selected
   * filter groups. However, if this option is set, the filter will disable
   * collisions against all colliders except for those in the selected filter
   * groups.
   */
  getInvertFilteredGroupsAttr(): Attribute {
    return this.prim.getAttr(UsdPhysicsTokens.physicsInvertFilteredGroups)!
  }
  createInvertFilteredGroupsAttr(defaultValue?: unknown, writeSparsely = false): Attribute {
    return this._createAttr(UsdPhysicsTokens.physicsInvertFilteredGroups, "bool", false, "varying", defaultValue, writeSparsely)
  }

  /**
   * References a list of PhysicsCollisionGroups with which 
   * collisions should be ignored.
   */
  getFilteredGroupsRel(): Rel {
    return this.prim.rel(UsdPhysicsTokens.physicsFilteredGroups)
  }
  createFilteredGroupsRel(): Rel {
    return this.prim.createRelationship(UsdPhysicsTokens.physicsFilteredGroups, false)
  }

  // --(BEGIN CUSTOM CODE)--

  // Return the UsdCollectionAPI interface used for defining what colliders
  // belong to the CollisionGroup (collisionGroup.h:220-223,
  // collisionGroup.cpp:194-198).
  getCollidersCollectionAPI(): CollectionAPI {
    return new CollectionAPI(this.prim, this.stage, UsdPhysicsTokens.colliders)
  }

  // Compute a table encoding all the collision groups filter rules for a
  // stage. This can be used as a reference to validate an implementation of
  // the collision groups filters. The returned table is diagonally symmetric
  // (collisionGroup.h:252-257, collisionGroup.cpp:238-391).
  static computeCollisionGroupTable(stage: Stage): CollisionGroupTable {
    // First, collect all the collision groups, as we want to iterate over them
    // several times
    const allSceneGroups: CollisionGroup[] = []
    // UsdPrimRange(stage.GetPseudoRoot()) visits the pseudo-root, which is
    // never a CollisionGroup, followed by the same prims as UsdPrimRange::Stage.
    const range = PrimRange.stage(stage)
    for (const prim of range) {
      if (prim.isA(CollisionGroup.typeName)) {
        allSceneGroups.push(new CollisionGroup(prim, stage))
      }
    }

    // Assign a number to every collision group; in order to handle merge
    // groups, some prims will have non-unique indices
    // Using SdfPath, rather than prim, as the filtered groups rel gives us a
    // path.
    const primPathToIndex = new Map<string, number>()
    const mergeGroupNameToIndex = new Map<string, number>()
    let nextPrimId = 0

    for (const collisionGroup of allSceneGroups) {
      const mergeGroupAttr = collisionGroup.getMergeGroupNameAttr()

      // If the group doesn't have a merge group, we can just add it to the
      // table:
      if (!_isAuthored(mergeGroupAttr)) {
        primPathToIndex.set(collisionGroup.path, nextPrimId)
        nextPrimId++
      } else {
        const v = mergeGroupAttr.get()
        const mergeGroupName = typeof v === 'string' ? v : ''
        const foundGroup = mergeGroupNameToIndex.get(mergeGroupName)
        if (foundGroup !== undefined) {
          primPathToIndex.set(collisionGroup.path, foundGroup)
        } else {
          mergeGroupNameToIndex.set(mergeGroupName, nextPrimId)
          primPathToIndex.set(collisionGroup.path, nextPrimId)
          nextPrimId++
        }
      }
    }

    // std::map::operator[] value-initializes (to 0) entries for paths that
    // are not collision groups (collisionGroup.cpp:300, 311, 372-375).
    const indexOf = (path: string): number => {
      let idx = primPathToIndex.get(path)
      if (idx === undefined) {
        idx = 0
        primPathToIndex.set(path, idx)
      }
      return idx
    }

    // Now, we've seen "nextPrimId" different unique groups after accounting
    // for the merge groups. Calculate the collision table for those groups.

    // First, resize the table and set to default-collide. We're only going to
    // use the upper diagonal, as the table is symmetric:
    const mergedTable: boolean[] = new Array<boolean>(((nextPrimId + 1) * nextPrimId) / 2).fill(true)

    for (const groupA of allSceneGroups) {
      const groupAIdx = indexOf(groupA.path)

      // Extract the indices for each filtered group in "prim":
      const filteredGroupIndices: number[] = []
      {
        const filteredGroups = groupA.getFilteredGroupsRel()
        const filteredTargets = filteredGroups.getTargets()
        for (const path of filteredTargets) {
          filteredGroupIndices.push(indexOf(path))
        }
      }

      const invertedAttr = groupA.getInvertFilteredGroupsAttr()
      const invertedFilter = invertedAttr?.get() === true

      // Now, we are ready to apply the filter rules for "prim":
      if (!_isAuthored(invertedAttr) || !invertedFilter) {
        // This is the usual case; collisions against all the
        // filteredTargets should be disabled
        for (const groupBIdx of filteredGroupIndices) {
          // Disable aIdx -v- bIdx
          const minGroup = Math.min(groupAIdx, groupBIdx)
          const maxGroup = Math.max(groupAIdx, groupBIdx)
          const tableIndex = _getCollisionTableIndex(minGroup, maxGroup, nextPrimId)
          mergedTable[tableIndex] = false
        }
      } else {
        // This is the less common case; disable collisions against all
        // groups except the filtered targets
        const requestedGroups = new Set<number>(filteredGroupIndices)
        for (let groupBIdx = 0; groupBIdx < nextPrimId; groupBIdx++) {
          if (!requestedGroups.has(groupBIdx)) {
            // Disable aIdx -v- bIdx
            const minGroup = Math.min(groupAIdx, groupBIdx)
            const maxGroup = Math.max(groupAIdx, groupBIdx)
            const tableIndex = _getCollisionTableIndex(minGroup, maxGroup, nextPrimId)
            mergedTable[tableIndex] = false
          }
        }
      }
    }

    // Finally, we can calculate the output table, based on the merged table
    const res = new CollisionGroupTable()
    for (const collisionGroup of allSceneGroups) {
      res._groups.push(collisionGroup.prim.path)
    }
    res._enabled = new Array<boolean>(((res._groups.length + 1) * res._groups.length) / 2).fill(true)

    // Iterate over every group A and B, and use the merged table to determine
    // if they collide.
    for (let iA = 0; iA < allSceneGroups.length; iA++) {
      for (let iB = iA; iB < allSceneGroups.length; iB++) {
        // Determine if the groups at iA and iB collide:
        const groupAId = indexOf(allSceneGroups[iA]!.path)
        const groupBId = indexOf(allSceneGroups[iB]!.path)
        // Upstream passes the merged ids unordered here
        // (collisionGroup.cpp:376-377); kept as-is.
        const mergedTableIndex = _getCollisionTableIndex(groupAId, groupBId, nextPrimId)
        const enabledInMergeTable = mergedTable[mergedTableIndex]!

        // And use that to populate the output table:
        const minGroup = Math.min(iA, iB)
        const maxGroup = Math.max(iA, iB)
        const tableIndex = _getCollisionTableIndex(minGroup, maxGroup, allSceneGroups.length)
        res._enabled[tableIndex] = enabledInMergeTable
      }
    }

    return res
  }
}

import { CollectionAPI, PrimRange } from 'typescript-usd/usd'

// UsdProperty::IsAuthored (pxr/usd/usd/property.cpp:128-139): true when any
// layer in the prim index has a spec for the property.
function _isAuthored(attr: Attribute | undefined): boolean {
  return attr !== undefined && attr.getPropertyStack().length > 0
}

// Helper private function to get index into the collision table
// Given indices of the 2 collision groups idxA < idxB and current group size
// (collisionGroup.cpp:183-192)
function _getCollisionTableIndex(idxA: number, idxB: number, groupSize: number): number {
  const numSkippedEntries = (idxA * idxA + idxA) / 2
  return (idxA * groupSize - numSkippedEntries + idxB)
}

// Utility structure generated by ComputeCollisionGroupTable(); contains a
// table describing which pairs of collision groups have collisions
// enabled/disabled by the filtering rules (collisionGroup.h:225-250).
export class CollisionGroupTable {
  // All collision groups known to this table
  _groups: string[] = []
  // 2D table, with one element per collision-group-pair. Entry is false
  // if collision is disabled by a filtering rule.
  _enabled: boolean[] = []

  // Return the set of all UsdPhysicsCollisionGroup which this table contains
  // (collisionGroup.cpp:200-204). Python wraps this as GetGroups
  // (wrapCollisionGroup.cpp:139-143).
  getCollisionGroups(): readonly string[] {
    return this._groups
  }
  getGroups(): string[] {
    return [...this._groups]
  }

  // Return true if the groups at indices idxA and idxB collide
  // (collisionGroup.cpp:206-225), or if the groups primA and primB collide
  // (collisionGroup.cpp:227-235). The Python wrapper also accepts
  // CollisionGroup and UsdPrim arguments (wrapCollisionGroup.cpp:145-179).
  isCollisionEnabled(a: number | string | CollisionGroup | Prim, b: number | string | CollisionGroup | Prim): boolean {
    if (typeof a === 'number' && typeof b === 'number') {
      return this._isCollisionEnabledIdx(a, b)
    }
    const toPath = (x: number | string | CollisionGroup | Prim): string | undefined =>
      typeof x === 'string' ? x
        : x instanceof CollisionGroup ? x.prim.path
          : typeof x === 'number' ? undefined
            : x.path
    const pathA = toPath(a), pathB = toPath(b)
    if (pathA === undefined || pathB === undefined) return true
    const ia = this._groups.indexOf(pathA)
    const ib = this._groups.indexOf(pathB)
    return this._isCollisionEnabledIdx(ia < 0 ? this._groups.length : ia, ib < 0 ? this._groups.length : ib)
  }

  private _isCollisionEnabledIdx(idxA: number, idxB: number): boolean {
    // check if indices are legal
    // - both idxA and idxB are by definition >=0
    // - are < the group size.
    if (idxA >= 0 && idxB >= 0 && idxA < this._groups.length && idxB < this._groups.length) {
      const minGroup = Math.min(idxA, idxB)
      const maxGroup = Math.max(idxA, idxB)
      const tableIndex = _getCollisionTableIndex(minGroup, maxGroup, this._groups.length)
      return this._enabled[tableIndex]!
    }

    // If the groups aren't in the table or we've been passed invalid groups,
    // return true, as groups will collide by default.
    return true
  }
}
